#!/usr/bin/env bash
# Every detector fixture, piped through the generated scripts beside this file.
# `relearn check` ran the same fixtures in Rust; this runs them on the
# production path, because the hook is `grep -E` and the check is not.
# Generated by relearn; edit the rule files, never this script.
set -uo pipefail
export LC_ALL=C MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*'

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
if ! command -v jq >/dev/null 2>&1; then
  echo "DISARMED (exit 2, not a pass): jq is not on PATH, so no fixture ran"
  exit 2
fi
work="$(mktemp -d)" || { echo "FAIL: no scratch directory"; exit 1; }
trap 'rm -rf "$work"' EXIT
pass=0
failed=0

# run <script> <expect hit|clean> <action block|warn> <path> <text> [sibling...]
run() {
  local script="$1" expect="$2" action="$3" path="$4" text="$5"
  shift 5
  local case_dir="$work/$((pass + failed))"
  local target="$case_dir/$path"
  mkdir -p "$(dirname "$target")"
  local sibling
  for sibling in "$@"; do : > "$(dirname "$target")/$sibling"; done
  local out got
  out="$(jq -nc --arg p "$target" --arg c "$text" \
    '{tool_name:"Write",tool_input:{file_path:$p,content:$c}}' \
    | bash "$here/$script" 2>"$work/stderr")"
  got=$?
  local err
  err="$(cat "$work/stderr")"
  local ok=no
  case "$expect:$action" in
    clean:*) [ "$got" -eq 0 ] && [ -z "$out" ] && [ -z "$err" ] && ok=yes ;;
    hit:block) [ "$got" -eq 2 ] && [ -n "$err" ] && ok=yes ;;
    hit:warn) [ "$got" -eq 0 ] && case "$out" in *additionalContext*) true ;; *) false ;; esac && ok=yes ;;
  esac
  if [ "$ok" = yes ]; then
    pass=$((pass + 1))
  else
    failed=$((failed + 1))
    printf 'FAIL  %s  %s expected %s (%s): exit %s, stdout %s bytes, stderr %s bytes\n' \
      "$script" "$path" "$expect" "$action" "$got" "${#out}" "${#err}"
  fi
}

# no-anyhow-in-lib
run 'no-anyhow-in-lib.sh' hit block 'src/lib.rs' 'use anyhow::Result;'
run 'no-anyhow-in-lib.sh' clean block 'src/lib.rs' 'use thiserror::Error;'
run 'no-anyhow-in-lib.sh' clean block 'src/lib.rs' 'use anyhow::Result; // allow:anyhow'
run 'no-anyhow-in-lib.sh' clean block 'README.md' 'anyhow is fine in prose'
run 'no-anyhow-in-lib.sh' clean block 'src/main.rs' 'use anyhow::Result;'
run 'no-anyhow-in-lib.sh' clean block 'src/lib.rs' 'use anyhow_ext::Thing;'
# no-case-collision
run 'no-case-collision.sh' hit block 'docs/README.md' '' 'readme.md'
run 'no-case-collision.sh' clean block 'docs/NOTES.md' '' 'readme.md'
run 'no-case-collision.sh' clean block 'docs/readme.md' '' 'readme.md'
# no-embedded-local-llm
run 'no-embedded-local-llm.sh' hit warn 'Cargo.toml' 'ollama-rs = "0.2"'
run 'no-embedded-local-llm.sh' hit warn 'src/summarise.rs' 'let client = Ollama::new("http://localhost", 11434);'
run 'no-embedded-local-llm.sh' hit warn 'src/summarise.py' 'resp = requests.post("http://localhost:11434/api/generate", json=body)'
run 'no-embedded-local-llm.sh' clean warn 'Cargo.toml' 'reqwest = { version = "0.12", default-features = false }'
run 'no-embedded-local-llm.sh' clean warn 'src/summarise.rs' 'let client = Ollama::new("http://localhost", 11434); // allow:local-model: tokeniser count only'
run 'no-embedded-local-llm.sh' clean warn 'docs/models.md' 'We considered Ollama and refused it.'
# no-expect-empty-msg
run 'no-expect-empty-msg.sh' hit block 'src/lib.rs' 'let x = f().expect("");'
run 'no-expect-empty-msg.sh' hit block 'src/lib.rs' 'let x = f().expect("ok");'
run 'no-expect-empty-msg.sh' clean block 'src/lib.rs' 'let x = f().expect("config parsed at startup");'
run 'no-expect-empty-msg.sh' clean block 'src/lib.rs' 'let x = f().expect(""); // allow:expect-msg'
run 'no-expect-empty-msg.sh' clean block 'src/lib_test.rs' 'let x = f().expect("");'
# no-unwrap-in-src
run 'no-unwrap-in-src.sh' hit block 'src/lib.rs' 'let x = f().unwrap();'
run 'no-unwrap-in-src.sh' clean block 'src/lib.rs' 'let x = f()?;'
run 'no-unwrap-in-src.sh' clean block 'src/lib.rs' 'let x = f().unwrap(); // allow:unwrap'
run 'no-unwrap-in-src.sh' clean block 'src/foo_tests.rs' 'let x = f().unwrap();'
run 'no-unwrap-in-src.sh' clean block 'src/lib.rs' '// never do f().unwrap()'
run 'no-unwrap-in-src.sh' clean block 'src/lib.rs' 'let x = f().unwrap_or(0);'
run 'no-unwrap-in-src.sh' clean block 'tests/it.rs' 'let x = f().unwrap();'

if [ "$failed" -eq 0 ]; then
  echo "PASS: $pass detector fixture(s) agree with the generated scripts"
  exit 0
fi
echo "FAIL: $failed of $((pass + failed)) detector fixture(s) disagree with the generated scripts"
exit 1

